2.9 缓存工具封装由于缓存问题非常常见，如果每个业务都解决缓存穿透、缓存击穿（缓存雪崩一般使用redis集群解决，后面会学习），会给业务开发带来不小的压力，所以，我们需要工具类帮我们提供这些操作，而工具类需要我们手动书写。
方法1：将任意Java对象序列化为json并存储在string类型的key中，并且可以设置TTL过期时间
方法2：将任意Java对象序列化为json并存储在string类型的key中，并且可以设置逻辑过期时间，用于处理缓存击穿问题
方法3：根据指定的key查询缓存，并反序列化为指定类型，利用缓存空值的方式解决缓存穿透问题
方法4：根据指定的key查询缓存，并反序列化为指定类型，需要利用逻辑过期解决缓存击穿问题
package com.hmdp.utils;

import cn.hutool.core.util.BooleanUtil;
import cn.hutool.core.util.StrUtil;
import cn.hutool.json.JSONObject;
import cn.hutool.json.JSONUtil;
import lombok.extern.slf4j.Slf4j;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Component;

import java.time.LocalDateTime;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.function.Function;

@Slf4j
@Component
public class CacheClientUtil &#123;
private final StringRedisTemplate stringRedisTemplate;

private static final ExecutorService CACHE_REBUILD_EXECUTOR = Executors.newFixedThreadPool(10);

private static final Long CACHE_NULL_TTL = 2L;

private static final String LOCK_SHOP_KEY = "lock:shop:";

public CacheClientUtil(StringRedisTemplate stringRedisTemplate) &#123;
this.stringRedisTemplate = stringRedisTemplate;
&#125;

/**
* 将java对象序列化到redis的string类型中，并指定TTL
* @param key redis中对应的key
* @param value redis中key对应的对象
* @param TTL TTL
* @param unit TTL对应的单位
*/
public void set(String key, Object value, Long TTL, TimeUnit unit) &#123;
stringRedisTemplate.opsForValue().set(key, JSONUtil.toJsonStr(value), TTL, unit);
&#125;

/**
* 将java对象序列化到redis的string类型中，并指定逻辑TTL
* @param key redis中对应的key
* @param value redis中key对应的对象
* @param LogicalTTL 逻辑TTL
* @param unit 逻辑TTL对应的单位
*/
public void setWithLogicalExpire(String key, Object value, Long LogicalTTL, TimeUnit unit) &#123;
// 设置逻辑过期
RedisData redisData = new RedisData();
redisData.setData(value);
redisData.setExpireTime(LocalDateTime.now().plusSeconds(unit.toSeconds(LogicalTTL)));
// 写入Redis
stringRedisTemplate.opsForValue().set(key, JSONUtil.toJsonStr(redisData));
&#125;

/**
* 根据key查询缓存，并反序列化为指定类型，利用空值解决缓存穿透
* @param keyPrefix 缓存key前缀
* @param id 查询的使用的id
* @param type 返回值类型
* @param dbFallback 查询业务逻辑函数
* @param time key的TTL
* @param unit TTL对应的单位
* @param &lt;R> 返回值泛型
* @param &lt;ID> id泛型
* @return 返回最终查询的数据
*/
public &lt;R, ID> R queryByIdWithPassThrough(String keyPrefix, ID id, Class&lt;R> type, Function&lt;ID, R> dbFallback, Long time, TimeUnit unit) &#123;
String key = keyPrefix + id;
// 1.从redis查询商铺缓存
String json = stringRedisTemplate.opsForValue().get(key);
// 2.判断是否存在
if (StrUtil.isNotBlank(json)) &#123;
// 3.存在，直接返回
return JSONUtil.toBean(json, type);
&#125;
// 判断命中的是否是空值
if (json != null) &#123;
// 返回null
return null;
&#125;

// 4.不存在，根据id查询数据库
R r = dbFallback.apply(id);
// 5.不存在，返回null
if (r == null) &#123;
// 将空值写入redis
stringRedisTemplate.opsForValue().set(key, "", CACHE_NULL_TTL, TimeUnit.MINUTES);
// 返回null
return null;
&#125;
// 6.存在，写入redis
this.set(key, r, time, unit);
return r;
&#125;

/**
* 根据key查询缓存，并反序列化为指定类型，利用逻辑过期解决缓存击穿
* @param keyPrefix 缓存key前缀
* @param id 查询的使用的id
* @param type 返回值类型
* @param dbFallback 查询业务逻辑函数
* @param time key的TTL
* @param unit TTL对应的单位
* @param &lt;R> 返回值泛型
* @param &lt;ID> id泛型
* @return 返回最终查询的数据
*/
public &lt;R, ID> R queryWithLogicalExpire(String keyPrefix, ID id, Class&lt;R> type, Function&lt;ID, R> dbFallback, Long time, TimeUnit unit) &#123;
String key = keyPrefix + id;
// 1.从redis查询商铺缓存
String json = stringRedisTemplate.opsForValue().get(key);
// 2.判断是否存在
if (StrUtil.isBlank(json)) &#123;
// 3.存在，直接返回
return null;
&#125;
// 4.命中，需要先把json反序列化为对象
RedisData redisData = JSONUtil.toBean(json, RedisData.class);
R r = JSONUtil.toBean((JSONObject) redisData.getData(), type);
LocalDateTime expireTime = redisData.getExpireTime();
// 5.判断是否过期
if (expireTime.isAfter(LocalDateTime.now())) &#123;
// 5.1.未过期，直接返回店铺信息
return r;
&#125;
// 5.2.已过期，需要缓存重建
// 6.缓存重建
// 6.1.获取互斥锁
String lockKey = LOCK_SHOP_KEY + id;
boolean isLock = tryLock(lockKey);
// 6.2.判断是否获取锁成功
if (isLock) &#123;
// 6.3.成功，开启独立线程，实现缓存重建
CACHE_REBUILD_EXECUTOR.submit(() -> &#123;
try &#123;
// 查询数据库
R newR = dbFallback.apply(id);
// 重建缓存
this.setWithLogicalExpire(key, newR, time, unit);
&#125; catch (Exception e) &#123;
throw new RuntimeException(e);
&#125; finally &#123;
// 释放锁
unlock(lockKey);
&#125;
&#125;);
&#125;
// 6.4.返回过期的商铺信息
return r;
&#125;

/**
* 根据key查询缓存，并反序列化为指定类型，利用互斥锁解决缓存击穿，同时利用缓存空值解决了缓存穿透
* @param keyPrefix 缓存key前缀
* @param id 查询的使用的id
* @param type 返回值类型
* @param dbFallback 查询业务逻辑函数
* @param time key的TTL
* @param unit TTL对应的单位
* @param &lt;R> 返回值泛型
* @param &lt;ID> id泛型
* @return 返回最终查询的数据
*/
public &lt;R, ID> R queryWithMutex(String keyPrefix, ID id, Class&lt;R> type, Function&lt;ID, R> dbFallback, Long time, TimeUnit unit) &#123;
String key = keyPrefix + id;
// 1.从redis查询商铺缓存
String shopJson = stringRedisTemplate.opsForValue().get(key);
// 2.判断是否存在
if (StrUtil.isNotBlank(shopJson)) &#123;
// 3.存在，直接返回
return JSONUtil.toBean(shopJson, type);
&#125;
// 判断命中的是否是空值
if (shopJson != null) &#123;
// 返回一个错误信息
return null;
&#125;


// 4.实现缓存重建
// 4.1.获取互斥锁
String lockKey = LOCK_SHOP_KEY + id;
R r = null;
try &#123;
boolean isLock = tryLock(lockKey);
// 4.2.判断是否获取成功
if (!isLock) &#123;
// 4.3.获取锁失败，休眠并重试
Thread.sleep(50);
return queryWithMutex(keyPrefix, id, type, dbFallback, time, unit);
&#125;
// 4.4.获取锁成功，根据id查询数据库
r = dbFallback.apply(id);
// 5.不存在，返回错误
if (r == null) &#123;
// 将空值写入redis
stringRedisTemplate.opsForValue().set(key, "", CACHE_NULL_TTL, TimeUnit.MINUTES);
// 返回错误信息
return null;
&#125;
// 6.存在，写入redis
this.set(key, r, time, unit);
&#125; catch (InterruptedException e) &#123;
throw new RuntimeException(e);
&#125; finally &#123;
// 7.释放锁
unlock(lockKey);
&#125;
// 8.返回
return r;
&#125;

private boolean tryLock(String key) &#123;
Boolean flag = stringRedisTemplate.opsForValue().setIfAbsent(key, "1", 10, TimeUnit.SECONDS);
return BooleanUtil.isTrue(flag);
&#125;

private void unlock(String key) &#123;
stringRedisTemplate.delete(key);
&#125;
&#125;

