XGROUP CREATE stream.orders g1 0 MKSTREAM

修改Lua脚本，最终脚本内容如下：
-- 1.参数列表
-- 1.1.优惠券id
local voucherId = ARGV[1]
-- 1.2.用户id
local userId = ARGV[2]
-- 1.3.订单id
local orderId = ARGV[3]

-- 2.数据key
-- 2.1.库存key
local stockKey = 'seckill:stock:' .. voucherId
-- 2.2.订单key
local orderKey = 'seckill:order:' .. voucherId

-- 3.脚本业务
-- 3.1.判断库存是否充足 get stockKey
if(tonumber(redis.call('get', stockKey)) &lt;= 0) then
-- 3.2.库存不足，返回1
return 1
end
-- 3.2.判断用户是否下单 SISMEMBER orderKey userId
if(redis.call('sismember', orderKey, userId) == 1) then
-- 3.3.存在，说明是重复下单，返回2
return 2
end
-- 3.4.扣库存 incrby stockKey -1
redis.call('incrby', stockKey, -1)
-- 3.5.下单（保存用户）sadd orderKey userId
redis.call('sadd', orderKey, userId)
-- 3.6.发送消息到队列中，XADD stream.orders * k1 v1 k2 v2
redis.call('xadd', 'stream.orders', '*', 'userId', userId, 'voucherId', voucherId, 'id', orderId)
return 0

修改VoucherOrderServiceImpl的下单逻辑，最后完整代码如下：
@Service
public class VoucherOrderServiceImpl extends ServiceImpl&lt;VoucherOrderMapper, VoucherOrder> implements IVoucherOrderService &#123;
@Resource
private ISeckillVoucherService seckillVoucherService;
@Resource
private RedisIdWorker redisIdWorker;
@Resource
private StringRedisTemplate stringRedisTemplate;
@Resource
private RedissonClient redissonClient;
private static final DefaultRedisScript&lt;Long> SECKILL_SCRIPT;
//异步处理线程池
private static final ExecutorService SECKILL_ORDER_EXECUTOR = Executors.newSingleThreadExecutor();
private IVoucherOrderService proxy;
private static final String queueName = "stream.orders";

static &#123;
SECKILL_SCRIPT = new DefaultRedisScript&lt;>();
SECKILL_SCRIPT.setLocation(new ClassPathResource("seckill.lua"));
SECKILL_SCRIPT.setResultType(Long.class);
&#125;

//在类初始化之后执行，因为当这个类初始化好了之后，随时都是有可能要执行的
@PostConstruct
private void init() &#123;
SECKILL_ORDER_EXECUTOR.submit(new VoucherOrderHandler());
&#125;

private class VoucherOrderHandler implements Runnable &#123;
@Override
public void run() &#123;
// 初始化消费者组
try &#123;
// 创建消费者组，如果组已存在则忽略错误
stringRedisTemplate.opsForStream().createGroup(queueName, "g1");
&#125; catch (Exception e) &#123;
log.warn("消费者组 g1 已存在，跳过创建");
&#125;
while (true) &#123;
try &#123;
// 1.获取消息队列中的订单信息 XREADGROUP GROUP g1 c1 COUNT 1 BLOCK 2000 STREAMS stream.orders >
List&lt;MapRecord&lt;String, Object, Object>> list = stringRedisTemplate.opsForStream().read(
Consumer.from("g1", "c1"),
StreamReadOptions.empty().count(1).block(Duration.ofSeconds(5)),
StreamOffset.create(queueName, ReadOffset.lastConsumed())
);
// 2.判断订单信息是否为空
if (list == null || list.isEmpty()) &#123;
// 如果为null，说明没有消息，继续下一次循环
continue;
&#125;
// 3.解析消息中的订单信息
MapRecord&lt;String, Object, Object> record = list.get(0);
Map&lt;Object, Object> values = record.getValue();
VoucherOrder voucherOrder = BeanUtil.fillBeanWithMap(values, new VoucherOrder(), true);
// 4.如果获取成功，可以下单
//createVoucherOrder(voucherOrder);
handleVoucherOrder(voucherOrder);
// 5.确认消息 XACK stream.orders g1 id
stringRedisTemplate.opsForStream().acknowledge(queueName, "g1", record.getId());
&#125; catch (Exception e) &#123;
log.error("处理订单异常:", e);
//处理异常消息
handlePendingList();
&#125;
&#125;
&#125;

private void handlePendingList() &#123;
while (true) &#123;
try &#123;
// 1.获取pending-list中的订单信息 XREADGROUP GROUP g1 c1 COUNT 1 STREAMS stream.orders 0
List&lt;MapRecord&lt;String, Object, Object>> list = stringRedisTemplate.opsForStream().read(
Consumer.from("g1", "c1"),
StreamReadOptions.empty().count(1),
StreamOffset.create(queueName, ReadOffset.from("0"))
);
// 2.判断消息是否获取成功
if (list == null || list.isEmpty()) &#123;
// 如果获取失败，，说明pending-list没有异常消息，结束循环
break;
&#125;
// 3.解析消息中的订单信息
MapRecord&lt;String, Object, Object> record = list.get(0);
Map&lt;Object, Object> values = record.getValue();
VoucherOrder voucherOrder = BeanUtil.fillBeanWithMap(values, new VoucherOrder(), true);
// 4.如果获取成功，可以下单
handleVoucherOrder(voucherOrder);
// 4.确认消息 XACK stream.orders g1 id
stringRedisTemplate.opsForStream().acknowledge(queueName, "g1", record.getId());
&#125; catch (Exception e) &#123;
log.error("处理pendding订单异常", e);
try &#123;
Thread.sleep(20);
&#125; catch (InterruptedException ex) &#123;
ex.printStackTrace();
&#125;
&#125;
&#125;
&#125;
&#125;


private void handleVoucherOrder(VoucherOrder voucherOrder) &#123;
// 1.获取用户
Long userId = voucherOrder.getUserId();
// 2.创建锁对象
RLock redisLock = redissonClient.getLock("lock:order:" + userId);
// 3.尝试获取锁
boolean isLock = redisLock.tryLock();
// 4.判断是否获得锁成功
if (!isLock) &#123;
// 获取锁失败，直接返回失败或者重试
log.error("不允许重复下单！");
return;
&#125;
try &#123;
//注意：由于是spring的事务是放在threadLocal中，此时的是多线程，事务会失效
proxy.createVoucherOrder(voucherOrder);
&#125; finally &#123;
// 释放锁
redisLock.unlock();
&#125;
&#125;

@Override
@Transactional
public void createVoucherOrder(VoucherOrder voucherOrder) &#123;
Long userId = voucherOrder.getUserId();
// 5.1.查询订单
int count = query().eq("user_id", userId).eq("voucher_id", voucherOrder.getVoucherId()).count();
// 5.2.判断是否存在
if (count > 0) &#123;
// 用户已经购买过了
log.error("用户已经购买过一次！");
&#125;
// 6.扣减库存
boolean success = seckillVoucherService.update()
.setSql("stock = stock - 1") // set stock = stock - 1
.eq("voucher_id", voucherOrder.getVoucherId()).gt("stock", 0) // where id = ? and stock > 0
.update();
if (!success) &#123;
// 扣减失败
log.error("库存不足！");
&#125;
// 7.创建订单
save(voucherOrder);
&#125;

