@Test
void testScan() &#123;
int maxLen = 0;
long len = 0;

String cursor = "0";
do &#123;
// 扫描并获取一部分key
ScanResult&lt;String> result = jedis.scan(cursor);
// 记录cursor
cursor = result.getCursor();
List&lt;String> list = result.getResult();
if (list == null || list.isEmpty()) &#123;
break;
&#125;
