if (len >= maxLen) &#123;
System.out.printf("Found big key : %s, type: %s, length or size: %d %n", key, type, len);
&#125;
&#125;
&#125; while (!cursor.equals("0"));
&#125;

@AfterEach
void tearDown() &#123;
if (jedis != null) &#123;
jedis.close();
&#125;
&#125;

&#125;

