终止模式之两阶段终止（优雅终止线程）核心思想：给线程预留收尾、料理后事的时间，避免强制终止导致数据异常、资源未释放
错误终止思路stop()方法：强制杀死线程，若线程持有锁，会导致锁无法释放，引发死锁System.exit()：终止整个程序，无法仅终止单个线程

方案一：基于 isInterrupted 实现

class TPTInterrupt {
    private Thread thread;
    public void start(){
        thread = new Thread(() -> {
            while(true) {
                Thread current = Thread.currentThread();
                if(current.isInterrupted()) {
                    log.debug("料理后事");
                    break;
                }
                try {
                    Thread.sleep(1000);
                    log.debug("将结果保存");
                } catch (InterruptedException e) {
                    // 捕获异常后重新设置打断标记
                    current.interrupt();
                }
                // 执行监控业务
            }
        },"监控线程");
        thread.start();
    }
    public void stop() {
        thread.interrupt();
    }
}


