模拟代理实现
import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.lang.reflect.UndeclaredThrowableException;

// ⬇️这就是 jdk 代理类的源码, 秘密都在里面
public class $Proxy0 extends Proxy implements A12.Foo &#123;

    public $Proxy0(InvocationHandler h) &#123;
        super(h);
    &#125;
    // ⬇️3. 进入代理方法
    public void foo() &#123;
        try &#123;
            // ⬇️4. 回调 InvocationHandler
            h.invoke(this, foo, new Object[0]);
        &#125; catch (RuntimeException | Error e) &#123;
            throw e;
        &#125; catch (Throwable e) &#123;
            throw new UndeclaredThrowableException(e);
        &#125;
    &#125;

    @Override
    public int bar() &#123;
        try &#123;
            Object result = h.invoke(this, bar, new Object[0]);
            return (int) result;
        &#125; catch (RuntimeException | Error e) &#123;
            throw e;
        &#125; catch (Throwable e) &#123;
            throw new UndeclaredThrowableException(e);
        &#125;
    &#125;

    static Method foo;
    static Method bar;
    static &#123;
        try &#123;
            foo = A12.Foo.class.getMethod("foo");
            bar = A12.Foo.class.getMethod("bar");
        &#125; catch (NoSuchMethodException e) &#123;
            throw new NoSuchMethodError(e.getMessage());
        &#125;
    &#125;
&#125;

收获💡代理一点都不难，无非就是利用了多态、反射的知识

方法重写可以增强逻辑，只不过这【增强逻辑】千变万化，不能写死在代理内部
通过接口回调将【增强逻辑】置于代理类之外
配合接口方法反射（是多态调用），就可以再联动调用目标方法
会用 arthas 的 jad 工具反编译代理类
限制⛔：代理增强是借助多态来实现，因此成员变量、静态方法、final 方法均不能通过代理实现

