buf1.writeBytes(new byte[]&#123;1, 2, 3, 4, 5&#125;);
ByteBuf buf2 = ByteBufAllocator.DEFAULT.buffer(5);
buf2.writeBytes(new byte[]&#123;6, 7, 8, 9, 10&#125;);
