网络 AIOpublic class AioServer &#123;
    public static void main(String[] args) throws IOException &#123;
        AsynchronousServerSocketChannel ssc = AsynchronousServerSocketChannel.open();
        ssc.bind(new InetSocketAddress(8080));
        ssc.accept(null, new AcceptHandler(ssc));
        System.in.read();
    &#125;

    private static void closeChannel(AsynchronousSocketChannel sc) &#123;
        try &#123;
            System.out.printf("[%s] %s close\n", Thread.currentThread().getName(), sc.getRemoteAddress());
            sc.close();
        &#125; catch (IOException e) &#123;
            e.printStackTrace();
        &#125;
    &#125;

    private static class ReadHandler implements CompletionHandler&lt;Integer, ByteBuffer> &#123;
        private final AsynchronousSocketChannel sc;

        public ReadHandler(AsynchronousSocketChannel sc) &#123;
            this.sc = sc;
        &#125;

        @Override
        public void completed(Integer result, ByteBuffer attachment) &#123;
            try &#123;
                if (result == -1) &#123;
                    closeChannel(sc);
                    return;
                &#125;
                System.out.printf("[%s] %s read\n", Thread.currentThread().getName(), sc.getRemoteAddress());
                attachment.flip();
                System.out.println(Charset.defaultCharset().decode(attachment));
                attachment.clear();
                // 处理完第一个 read 时，需要再次调用 read 方法来处理下一个 read 事件
                sc.read(attachment, attachment, this);
            &#125; catch (IOException e) &#123;
                e.printStackTrace();
            &#125;
        &#125;

        @Override
        public void failed(Throwable exc, ByteBuffer attachment) &#123;
            closeChannel(sc);
            exc.printStackTrace();
        &#125;
    &#125;

    private static class WriteHandler implements CompletionHandler&lt;Integer, ByteBuffer> &#123;
        private final AsynchronousSocketChannel sc;

        private WriteHandler(AsynchronousSocketChannel sc) &#123;
            this.sc = sc;
        &#125;

        @Override
        public void completed(Integer result, ByteBuffer attachment) &#123;
            // 如果作为附件的 buffer 还有内容，需要再次 write 写出剩余内容
            if (attachment.hasRemaining()) &#123;
                sc.write(attachment);
            &#125;
        &#125;

        @Override
        public void failed(Throwable exc, ByteBuffer attachment) &#123;
            exc.printStackTrace();
            closeChannel(sc);
        &#125;
    &#125;

    private static class AcceptHandler implements CompletionHandler&lt;AsynchronousSocketChannel, Object> &#123;
        private final AsynchronousServerSocketChannel ssc;

        public AcceptHandler(AsynchronousServerSocketChannel ssc) &#123;
            this.ssc = ssc;
        &#125;

        @Override
        public void completed(AsynchronousSocketChannel sc, Object attachment) &#123;
            try &#123;
                System.out.printf("[%s] %s connected\n", Thread.currentThread().getName(), sc.getRemoteAddress());
            &#125; catch (IOException e) &#123;
                e.printStackTrace();
            &#125;
            ByteBuffer buffer = ByteBuffer.allocate(16);
            // 读事件由 ReadHandler 处理
            sc.read(buffer, buffer, new ReadHandler(sc));
            // 写事件由 WriteHandler 处理
            sc.write(Charset.defaultCharset().encode("server hello!"), ByteBuffer.allocate(16), new WriteHandler(sc));
            // 处理完第一个 accpet 时，需要再次调用 accept 方法来处理下一个 accept 事件
            ssc.accept(null, this);
        &#125;

        @Override
        public void failed(Throwable exc, Object attachment) &#123;
            exc.printStackTrace();
        &#125;
    &#125;
&#125;

计算属性 &amp;&amp; watch一、computed
减少模板中表达式的使用
当计算属性在模板中使用，并且计算属性的依赖值发生改变的时候就会触发它的更改。如果不发生变化，使用的就是缓存的属性值
computed 中使用 dirty 来标识是否需要重新计算，computed 中使用 value 变量缓存上一次计算结果的值，如果连续调用同一个计算属性会返回缓存的值
计算属性中的 getter 函数要求是没有副作用的

1.1 计算属性 VS 方法
计算属性是基于它们的响应式依赖进行缓存的。只在相关响应式依赖发生改变时它们才会重新求值。多次访问计算属性会立即返回之前的计算结果，而不必再次执行函数。
相比之下，每当触发重新渲染时，调用方法将总会再次执行函数。

二、watch 侦听器
适合在调试的时候使用
watch 是在属性有改变的时候调用对应的方法

// 想要监听一个对象的深层变化时，需要加上 deep 关键字
watch: &#123;
  // 监听的变量只接受以 . 为分隔的路径(obj.person.name)
  combo: &#123;
    handler: function() &#123;
      ......
    &#125;,
    // 想要监听对象内部值的变化，需要指定 deep 为 true(值得注意的是，监听数组的变化不需要这样做)
    deep: true
  &#125;
&#125;

1.2 侦听器VS计算属性
计算属性是依赖的属性发生变化时，计算属性跟着变化，并且主要得到的是一个属性。
侦听器不是为了得到一个属性，而是期望在某些属性变化的时候能触发一些函数或者语句

Vue3 响应式数据
Vue 能够跟踪对响应式对象属性的访问与更改操作(对 Proxy 的更改和访问会被 Vue 跟踪到， 对 obj 的更改和访问不会被 Vue 跟踪到)
在 Vue3 中，状态都是 默认、深层响应式 的


Vue 社区观点，默认使用 ref，并在需要对事物分组时使用 reactive

// 一、用 ref
const foo = ref(0);
const bar = ref([1, 2, 3]);

setTimeout(() => &#123;
  // 直接使用未分组的数据，需要 .value
  foo.value++;
  bar.value.push(4);
&#125;, 2000);

// 二、分组时使用 reactive

// 2.1 分组使用
const state = reactive(&#123;
  foo: 0,
  bar: [1, 2, 3],
&#125;);

setTimeout(() => &#123;
  state.foo++;
  state.bar.push(4);
&#125;, 2000);

// 2.2 reactive 整体替换
// 既然是分组，那么在实际使用中并不应该出现 `state = &#123;...&#125;` 的情况, 所以 reactive 不能整体替换的缺点也就消失了

// 2.3  解构使用
// 想要解构使用时，一律使用 toRefs()

const state = reactive(&#123;
  foo: ref(0),
  bar: ref([1, 2, 3]),
&#125;);

let &#123; foo, bar &#125; = toRefs(state);

setTimeout(() => &#123;
  foo.value++;
  bar.value.push(4);
&#125;, 2000);

// 2.4 和组合式函数搭配使用

// 三、第三方库的数据使用 shallowRef

// 3.1 更好的性能

// 3.2 在整体替换时，能触发 Vue 的响应式

一、ref()
reactive() 不能为 string, number, boolean 类型声明响应式，是因为 js 中没有给这三种值引用数据类型
ref() 将传入参数的值包装为一个带 .value 属性的 ref 对象(将一个基本类型的值变成引用类型的值之后，就可以把这个属性赋值，解构，或者是当做函数的参数传递了)
之前觉得 ref 的 .value 是额外的负担，但是网上有一些说法 .value 能清楚的标识出哪些是响应式变量，哪些是普通 JS 变量
ref 不仅仅是实现原始值的响应式方案，还用来解决响应式丢失问题

1.1 ref 的使用// 1. 对象整个替换时，仍能保持响应式
const state = ref(&#123;
  foo: 1,
  bar: [1, 2, 3],
&#125;);

setTimeout(() => &#123;
  state.value = &#123;
    foo: 2,
    bar: [1, 2, 3, 4],
  &#125;;
&#125;, 1000);

// 2. ref 和 解构用法搭配
// 2.1 ref() 整个对象时，解构也不是很友好
const state = ref(&#123;
  foo: 1,
  bar: [1, 2, 3],
&#125;);

let &#123; foo, bar &#125; = state.value;

setTimeout(() => &#123;
  foo++; // 原始数据类型值： 已经失去响应式
  bar.push(4); // 引用数据类型值： 仍保留响应式
&#125;, 1000);

// 2.2 将 ref() 分组到普通的 JS 对象中，解构不会丢失响应式，但是 state 对象本身无响应性
const state = &#123;
  foo: ref(1),
  bar: ref([1, 2, 3]),
&#125;;

let &#123; foo, bar &#125; = state;

setTimeout(() => &#123;
  foo.value++; // foo 和 state.foo 会保持同步
  bar.value.push(4); // bar 和 state.bar 会保持同步
&#125;, 1000);

// 3. 解构时使用 ref 或者 refs
// ! 这种写法，数据既能整个替换，又能解构使用。属于比较全能的用法
const state = ref(&#123;
  foo: 1,
  bar: [1, 2, 3],
&#125;);

let &#123; foo, bar &#125; = toRefs(state.value);

setTimeout(() => &#123;
  foo.value++; // foo 和 state.foo 会保持同步
  bar.value.push(4); // bar 和 state.bar 会保持同步
&#125;, 1000);

1.2 解包
模板解包：当 ref 在模板中作为顶层属性(如果一个属性并不是顶层属性，可以使用解构的方式解出来)被访问时，它们会被自动”解包”，所以不需要使用 .value(若只是想展示数据那么无论是不是顶层对象都不需要.value, 只是说在{{}}语法中想把属性当做表达式计算时，只有顶层属性不需要加 .value)
非模版解包：当一个 ref 被嵌套在一个响应式对象中，作为属性被访问或更改时，它会自动解包，因此会表现得和一般的属性一样(不需要使用 .value 来取值), 当 ref 被嵌套在响应式数组中时，不会被解包

二、reactive()
仅对引用类型有效(对象，数组，Set，Map)等。(string, number, boolean)等原始类型无效，Proxy 是基于属性的访问进行响应式跟踪的。所以只能对引用类型进行跟踪。

2.1 reactive 的使用// 1. 整个替换时，会失去响应式
let state = reactive(&#123;
  foo: 1,
  bar: [1, 2, 3],
&#125;);

setTimeout(() => &#123;
  state = &#123;
    foo: 2,
    bar: [1, 2, 3, 4],
  &#125;;
&#125;, 1000);

// 2. 解构、将属性传递给函数时，原始数值类型值时，会失去响应式
let state = reactive(&#123;
  foo: 1,
  bar: [1, 2, 3],
&#125;);

let &#123; foo, bar &#125; = state;

setTimeout(() => &#123;
  foo++; // 原始数据类型值： 已经失去响应式
  bar.push(4); // 引用数据类型值： 仍保留响应式
&#125;, 1000);

// 3. 解构时使用 toRef 或者 toRefs
let state = reactive(&#123;
  foo: 1,
  bar: [1, 2, 3],
&#125;);

let &#123; foo, bar &#125; = toRefs(state);

setTimeout(() => &#123;
  foo.value++; // foo 和 state.foo 会保持同步
  bar.value.push(4); // bar 和 state.bar 会保持同步
&#125;, 1000);

